WITH release_scope AS MATERIALIZED ( SELECT snapshot.effective_release_id, member.package_version, convert_from(snapshot.canonical_bytes, 'UTF8')::jsonb AS manifest FROM catalog.release_manifest_v3_snapshots AS snapshot JOIN catalog.effective_release_packages AS member ON member.tenant_id = snapshot.tenant_id AND member.effective_release_id = snapshot.effective_release_id AND member.package_id = $2 WHERE snapshot.tenant_id = $1 AND snapshot.effective_release_id = $6 AND snapshot.manifest_digest = $7 AND convert_from(snapshot.canonical_bytes, 'UTF8')::jsonb #>> '{release,environment}' = $3 ), selected AS MATERIALIZED ( SELECT wiring.version, release_scope.effective_release_id, release_scope.package_version, wiring.graph_json, wiring.wiring_hash, release_scope.manifest, release_scope.effective_release_id AS release_id FROM release_scope JOIN catalog.wirings AS wiring ON wiring.tenant_id = $1 AND wiring.package_id = $2 AND wiring.package_version = release_scope.package_version AND wiring.wiring_id = $4 AND wiring.version = $5 WHERE EXISTS ( SELECT 1 FROM catalog.release_components AS member WHERE member.tenant_id = $1 AND member.effective_release_id = release_scope.effective_release_id AND member.wiring_package_id = $2 AND member.wiring_package_version = release_scope.package_version AND member.wiring_id = $4 AND member.wiring_version = $5 ) ) SELECT selected.version, selected.effective_release_id, selected.package_version, selected.graph_json::text, selected.wiring_hash, COALESCE( (SELECT jsonb_agg( jsonb_build_object( 'node-id', member.node_id, 'component', jsonb_build_object( 'scope', jsonb_build_object( 'tenant-id', $1::text, 'package-id', component.package_id, 'package-version', component.package_version ), 'component', component.component, 'interface-version', component.interface_version, 'operations', component.operations, 'component-digest', component.component_digest, 'imports', component.imports, 'imports-fingerprint', component.imports_fingerprint, 'effects', component.effects ) ) ORDER BY member.node_id COLLATE "C" ) FROM catalog.release_components AS member JOIN catalog.component_library AS component ON component.tenant_id = member.tenant_id AND component.package_id = member.package_id AND component.package_version = member.package_version AND component.component_digest = member.component_digest WHERE member.tenant_id = $1 AND member.effective_release_id = selected.release_id AND member.wiring_package_id = $2 AND member.wiring_package_version = selected.package_version AND member.wiring_id = $4 AND member.wiring_version = $5), '[]'::jsonb )::text AS node_components, COALESCE( (SELECT jsonb_agg( jsonb_build_object( 'scope', jsonb_build_object( 'tenant-id', $1::text, 'package-id', component.package_id, 'package-version', component.package_version ), 'component', component.component, 'interface-version', component.interface_version, 'operations', component.operations, 'component-digest', component.component_digest, 'imports', component.imports, 'imports-fingerprint', component.imports_fingerprint, 'effects', component.effects ) ORDER BY projected.ordinality ) FROM jsonb_array_elements(selected.manifest -> 'components') WITH ORDINALITY AS projected(definition, ordinality) JOIN catalog.effective_release_packages AS release_package ON release_package.tenant_id = $1 AND release_package.effective_release_id = selected.release_id AND release_package.package_id = projected.definition ->> 'package-id' JOIN catalog.component_library AS component ON component.tenant_id = release_package.tenant_id AND component.package_id = release_package.package_id AND component.package_version = release_package.package_version AND component.component = projected.definition ->> 'component' AND component.interface_version = projected.definition ->> 'interface-version' AND component.component_digest = projected.definition ->> 'digest'), '[]'::jsonb )::text AS components, jsonb_array_length(selected.manifest -> 'components') AS manifest_component_count FROM selected
